import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadMontserrat = makeLoadFont('Montserrat');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: playfairFamily } = loadPlayfair();

