export type CoffeeDecafAnimationProps = Record<string, any>;

// Modular Sub-component for individual steam paths
const SteamLine: React.FC<{ delay: number; offsetX: number; width: number; height: number }> = ({
  delay,
  offsetX,
  width,
  height,
}) => {
  const frame = useCurrentFrame();
  const progress = ((frame + delay) % 150) / 150; // Smooth 5-second loop at 30fps

  // Slowly drifts upwards
  const translateY = interpolate(progress, [0, 1], [80, -100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Fades in quickly, stays visible, then gently dissolves
  const opacity = interpolate(progress, [0, 0.25, 0.75, 1], [0, 0.22, 0.22, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Natural organic sinusoidal sway side-to-side
  const translateX = Math.sin(progress * Math.PI * 4) * 15 + offsetX;

  return (
    <path
      d="M 10 80 Q 25 50 10 20 T 25 -10"
      fill="none"
      stroke="rgba(255, 255, 255, 0.35)"
      strokeWidth="4"
      strokeLinecap="round"
      style={{
        transform: `translate(${width / 2 + translateX}px, ${height / 2 + translateY}px) scale(1.6)`,
        opacity,
        filter: "blur(6px)",
        transition: "none",
      }}
    />
  );
};

export const CoffeeDecafAnimation: React.FC<CoffeeDecafAnimationProps> = ({
  backgroundColor = "#FF5F33",
  transparentBackground = false,
  durationInSeconds = 6,
  cupColor = "#FFFFFF",
  coffeeColor = "#1a0d02",
  textColor = "#F5EBE0",
  finallyTextColor = "#FFFFFF",
  quoteColor = "#000000",
  finallyTextCount = 5,
  finallyTextFontSize = 36,
  centerTextFontSize = 72,
  innerRadiusPercent = 38,
  finallyWord = "FINALLY!",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // Safety variables for parsing colors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 1. CIRCULAR "FINALLY!" TEXT LOGIC
  // Generate repeated word with trailing spaces to create perfect uniform gaps
  const repeatedText = Array(finallyTextCount).fill(finallyWord).join("   ") + "   ";
  const characters = repeatedText.split("");
  const totalChars = characters.length;
  const radius = (Math.min(width, height) * innerRadiusPercent) / 100;

  // Slowly rotate the entire circular text structure over the active sequence
  const continuousSpin = interpolate(frame, [0, durationInFrames], [0, 40]);

  // 2. COFFEE CUP SPRING REVEAL (starts at frame 15)
  const cupSpring = spring({
    frame: frame - 15,
    fps,
    config: {
      damping: 14,
      mass: 0.8,
      stiffness: 90,
    },
  });
  const cupScale = frame >= 15 ? interpolate(cupSpring, [0, 1], [0, 1]) : 0;

  // Interpolated shadow properties based on cup scale to simulate altitude/depth
  const shadowOffset = interpolate(cupScale, [0, 1], [0, 20]);
  const shadowBlur = interpolate(cupScale, [0, 1], [0, 35]);
  const shadowOpacity = interpolate(cupScale, [0, 1], [0, 0.3]);

  // 3. INNER CENTRAL TEXT "GOOD DECAF" SEQUENCE STAGGER
  // "GOOD" starts fading & sliding at frame 50
  const goodSpring = spring({
    frame: frame - 50,
    fps,
    config: {
      damping: 12,
      mass: 0.6,
      stiffness: 100,
    },
  });
  const goodScale = frame >= 50 ? interpolate(goodSpring, [0, 1], [0.4, 1]) : 0;
  const goodOpacity = frame >= 50 ? interpolate(goodSpring, [0, 1], [0, 1]) : 0;
  const goodTranslateY = frame >= 50 ? interpolate(goodSpring, [0, 1], [30, 0]) : 30;

  // "DECAF" starts fading & sliding at frame 70
  const decafSpring = spring({
    frame: frame - 70,
    fps,
    config: {
      damping: 12,
      mass: 0.6,
      stiffness: 100,
    },
  });
  const decafScale = frame >= 70 ? interpolate(decafSpring, [0, 1], [0.4, 1]) : 0;
  const decafOpacity = frame >= 70 ? interpolate(decafSpring, [0, 1], [0, 1]) : 0;
  const decafTranslateY = frame >= 70 ? interpolate(decafSpring, [0, 1], [30, 0]) : 30;

  // 4. QUOTE MARK ANIMATION IN TOP LEFT (starts at frame 5)
  const quoteSpring = spring({
    frame: frame - 5,
    fps,
    config: {
      damping: 15,
      mass: 0.5,
      stiffness: 90,
    },
  });
  const quoteScale = frame >= 5 ? interpolate(quoteSpring, [0, 1], [0, 1]) : 0;
  const quoteOpacity = frame >= 5 ? interpolate(quoteSpring, [0, 1], [0, 0.9]) : 0;
  const quoteTranslateY = frame >= 5 ? interpolate(quoteSpring, [0, 1], [-30, 0]) : -30;

  // Dimensions of Coffee Cup Core elements
  const baseSize = Math.min(width, height);
  const cupOuterDiameter = baseSize * 0.46;
  const cupInnerDiameter = baseSize * 0.38;

  // Handle Dimension calculations (on right side of cup)
  const handleWidth = cupOuterDiameter * 0.28;
  const handleHeight = cupOuterDiameter * 0.22;
  const handleOffset = cupOuterDiameter * 0.44;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Background Bottom Editorial Gradient Vignette */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          height: "30%",
          background: "linear-gradient(to top, rgba(0, 0, 0, 0.4) 0%, rgba(0, 0, 0, 0) 100%)",
          pointerEvents: "none",
          zIndex: 1,
        }}
      />

      {/* Elegant Editorial Quote Mark */}
      <div
        style={{
          position: "absolute",
          left: width * 0.08,
          top: height * 0.08,
          fontFamily: playfairFamily,
          fontSize: "190px",
          fontWeight: "900",
          color: quoteColor,
          opacity: quoteOpacity,
          transform: `translateY(${quoteTranslateY}px) scale(${quoteScale})`,
          lineHeight: 1,
          transition: "none",
          zIndex: 2,
        }}
      >
        “
      </div>

      {/* CLOCKWISE REVEALING "FINALLY!" Typography Ring */}
      <div
        style={{
          position: "absolute",
          width,
          height,
          transform: `rotate(${continuousSpin}deg)`,
          transformOrigin: "center center",
          transition: "none",
          zIndex: 2,
        }}
      >
        {characters.map((char, i) => {
          const angle = (i / totalChars) * 360;
          const angleInRadians = (angle * Math.PI) / 180 - Math.PI / 2;
          const x = radius * Math.cos(angleInRadians);
          const y = radius * Math.sin(angleInRadians);

          // Clockwise sequential stagger timeline
          const revealStartFrame = 10 + (i / totalChars) * 60;
          const letterSpring = spring({
            frame: frame - revealStartFrame,
            fps,
            config: {
              damping: 12,
              mass: 0.5,
              stiffness: 110,
            },
          });

          const scale = frame >= revealStartFrame ? interpolate(letterSpring, [0, 1], [0, 1]) : 0;
          const opacity = frame >= revealStartFrame ? interpolate(letterSpring, [0, 1], [0, 1]) : 0;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: width / 2 + x,
                top: height / 2 + y,
                transform: `translate(-50%, -50%) rotate(${angle}deg) scale(${scale})`,
                opacity,
                fontSize: `${finallyTextFontSize}px`,
                fontWeight: "900",
                color: finallyTextColor,
                fontFamily: oswaldFamily,
                textTransform: "uppercase",
                transition: "none",
                whiteSpace: "pre",
              }}
            >
              {char}
            </div>
          );
        })}
      </div>

      {/* COFFEE CUP GROUP */}
      <div
        style={{
          position: "absolute",
          width,
          height,
          transform: `scale(${cupScale})`,
          filter: `drop-shadow(0px ${shadowOffset}px ${shadowBlur}px rgba(0, 0, 0, ${shadowOpacity}))`,
          pointerEvents: "none",
          transition: "none",
          zIndex: 3,
        }}
      >
        {/* Organic Ceramic Cup Handle */}
        <div
          style={{
            position: "absolute",
            left: width / 2 + handleOffset - handleWidth * 0.4,
            top: height / 2 - handleHeight / 2,
            width: handleWidth,
            height: handleHeight,
            border: `${baseSize * 0.02}px solid ${cupColor}`,
            borderRadius: "50% 30% 30% 50%",
            backgroundColor: bgColor,
            zIndex: 1,
            boxSizing: "border-box",
            transform: `rotate(-4deg)`,
            transition: "none",
          }}
        />

        {/* Outer Cup Ceramic Rim / Body */}
        <div
          style={{
            position: "absolute",
            left: width / 2 - cupOuterDiameter / 2,
            top: height / 2 - cupOuterDiameter / 2,
            width: cupOuterDiameter,
            height: cupOuterDiameter,
            borderRadius: "50%",
            background: `radial-gradient(circle, ${cupColor} 75%, #ebebeb 100%)`,
            border: "1px solid rgba(0,0,0,0.05)",
            boxSizing: "border-box",
            zIndex: 2,
            transition: "none",
          }}
        />

        {/* Inner Cup Coffee Container */}
        <div
          style={{
            position: "absolute",
            left: width / 2 - cupInnerDiameter / 2,
            top: height / 2 - cupInnerDiameter / 2,
            width: cupInnerDiameter,
            height: cupInnerDiameter,
            borderRadius: "50%",
            background: `radial-gradient(circle, #3d1c07 0%, ${coffeeColor} 70%, #0d0602 100%)`,
            border: `5px solid rgba(0, 0, 0, 0.15)`,
            boxSizing: "border-box",
            zIndex: 3,
            overflow: "hidden",
            transition: "none",
          }}
        >
          {/* Subtle Crema Swirl Texture */}
          <svg
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              opacity: 0.18,
              transition: "none",
            }}
            viewBox="0 0 100 100"
          >
            <path
              d="M 50 10 C 20 10 10 30 10 50 C 10 70 30 90 50 90 C 70 90 90 70 90 50 C 90 30 70 20 50 35 C 35 45 35 60 50 65 C 60 68 70 60 70 50"
              fill="none"
              stroke={textColor}
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeDasharray="8 12"
            />
          </svg>

          {/* Central Typography Layout */}
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              transform: "translate(-50%, -50%)",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              gap: "2px",
              width: "100%",
              height: "100%",
              zIndex: 5,
              transition: "none",
            }}
          >
            {/* GOOD TEXT */}
            <div
              style={{
                fontFamily: montserratFamily,
                fontSize: `${centerTextFontSize}px`,
                fontWeight: "900",
                color: textColor,
                transform: `scale(${goodScale}) translateY(${goodTranslateY}px)`,
                opacity: goodOpacity,
                letterSpacing: "6px",
                lineHeight: "1.1",
                textShadow: "0px 3px 6px rgba(0,0,0,0.6)",
                transition: "none",
              }}
            >
              GOOD
            </div>

            {/* DECAF TEXT */}
            <div
              style={{
                fontFamily: montserratFamily,
                fontSize: `${centerTextFontSize}px`,
                fontWeight: "900",
                color: textColor,
                transform: `scale(${decafScale}) translateY(${decafTranslateY}px)`,
                opacity: decafOpacity,
                letterSpacing: "6px",
                lineHeight: "1.1",
                textShadow: "0px 3px 6px rgba(0,0,0,0.6)",
                transition: "none",
              }}
            >
              DECAF
            </div>
          </div>
        </div>

        {/* Ambient Steam Layer overlaying coffee and text */}
        <svg
          style={{
            position: "absolute",
            width,
            height,
            zIndex: 4,
            pointerEvents: "none",
            transition: "none",
          }}
        >
          <SteamLine delay={0} offsetX={-45} width={width} height={height} />
          <SteamLine delay={50} offsetX={5} width={width} height={height} />
          <SteamLine delay={100} offsetX={45} width={width} height={height} />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

